          { id: 'screenshot-2-cccccccccccc', kind: 'screenshot', content: '<html>not a png</html>' },
          { id: 'test_report-3-dddddddddddd', kind: 'test_report', content: '{"suites":[]}' },
          { id: 'patch-4-eeeeeeeeeeee', kind: 'patch', content: 'diff --git a b\n' },
